import { Component } from '@angular/core';
import { Router } from '@angular/router';
import { AuthService } from '../services/auth.service';

@Component({
  selector: 'app-register',
  templateUrl: './register.component.html',
  styleUrls: ['../login/login.component.css']
})
export class RegisterComponent {
  email = '';
  password = '';
  firstName = '';
  lastName = '';
  dialecte = 'arabe';
  error = '';
  loading = false;

  constructor(private authService: AuthService, private router: Router) {}

  onRegister(): void {
    if (!this.email || !this.password || !this.firstName || !this.lastName) {
      this.error = 'يرجى تعبئة جميع الحقول المطلوبة';
      return;
    }
    this.loading = true;
    this.error = '';
    this.authService.register(this.email, this.password, this.firstName, this.lastName, this.dialecte).subscribe({
      next: () => {
        this.router.navigate(['/dashboard']);
      },
      error: (err) => {
        this.error = err.error?.message || "حدث خطأ أثناء التسجيل";
        this.loading = false;
      }
    });
  }
}
<div class="auth-container">
  <div class="auth-card glass-panel animate-fade-in">
    <div class="auth-header">
      <i class="fa-solid fa-user-plus gold-icon"></i>
      <h1 class="gradient-text">إنشاء حساب</h1>
      <p>انضمّ إلى مرشد وابدأ مسارك مع الذكاء الاصطناعي</p>
    </div>

    <form (ngSubmit)="onRegister()" class="auth-form">
      <div class="grid-2" style="gap: 0.75rem; margin-bottom: 0.5rem;">
        <div class="form-group">
          <label>الاسم الأول</label>
          <input type="text" [(ngModel)]="firstName" name="firstName" class="form-input" placeholder="Ahmed" required>
        </div>
        <div class="form-group">
          <label>اسم العائلة</label>
          <input type="text" [(ngModel)]="lastName" name="lastName" class="form-input" placeholder="Ibrahim" required>
        </div>
      </div>

      <div class="form-group">
          <label><i class="fa-solid fa-envelope"></i> البريد الإلكتروني</label>
        <input type="email" [(ngModel)]="email" name="email" class="form-input" placeholder="ahmed@example.com" required>
      </div>

      <div class="form-group">
          <label><i class="fa-solid fa-lock"></i> كلمة المرور</label>
        <input type="password" [(ngModel)]="password" name="password" class="form-input" placeholder="Test@123456" required>
      </div>

      <button type="submit" class="btn-primary w-full" [disabled]="loading">
        <i class="fa-solid fa-check" *ngIf="!loading"></i>
        <span>{{ loading ? 'جارٍ إنشاء الحساب...' : 'إنشاء حسابي' }}</span>
      </button>

      <div *ngIf="error" class="error-alert">
        <i class="fa-solid fa-triangle-exclamation"></i> {{ error }}
      </div>
    </form>

    <div class="auth-footer">
      <p>لديك حساب؟ <a routerLink="/login" class="gold-text">تسجيل الدخول</a></p>
    </div>
  </div>
</div>
